package calc

import "errors"

var (
	ErrNotPositive  = errors.New("amount must be positive")
	ErrInsufficient = errors.New("insufficient funds")
)

func withdraw(balance, amount int64) (int64, error) {
	if amount <= 0 {
		return 0, ErrNotPositive
	}
	if amount >= balance {
		return 0, ErrInsufficient
	}
	return balance - amount, nil
}

package calc

import (
	"errors"
	"testing"
)

func TestErrors(t *testing.T) {
	if got, err := withdraw(100, 30); err != nil || got != 70 {
		t.Errorf("withdraw(100, 30) = %d, %v, want 70", got, err)
	}
	if got, err := withdraw(50, 50); err != nil || got != 0 {
		t.Errorf("withdraw(50, 50) = %d, %v, want 0", got, err)
	}
	if _, err := withdraw(100, 0); !errors.Is(err, ErrNotPositive) {
		t.Errorf("withdraw(100, 0) error = %v, want ErrNotPositive", err)
	}
	if _, err := withdraw(10, 30); !errors.Is(err, ErrInsufficient) {
		t.Errorf("withdraw(10, 30) error = %v, want ErrInsufficient", err)
	}
}
